changeSet.sql:
UPDATE practice
SET adopted_base = (adopted_base - 'precomputeScript') || jsonb_build_object('practiceScript', adopted_base -> 'precomputeScript')
WHERE adopted_base -> 'precomputeScript' IS NOT NULL;
UPDATE curated_practice_override
SET adopted_base = (adopted_base - 'precomputeScript') || jsonb_build_object('practiceScript', adopted_base -> 'precomputeScript')
WHERE adopted_base -> 'precomputeScript' IS NOT NULL;

