changeSet.sql:
ALTER TABLE practice_result ADD COLUMN scope_key varchar(255), ADD COLUMN example jsonb, ADD COLUMN coverage jsonb, ADD COLUMN provenance jsonb;
UPDATE practice_result r SET scope_key = derived.scope_key FROM ( SELECT result.id, result.artifact_kind || ':' || result.artifact_id || ':' || COALESCE(revision.subject, practice.subject) || CASE WHEN COALESCE(revision.subject, practice.subject) = 'REVIEWER' AND jsonb_typeof(job.metadata -> 'review_id') = 'number' THEN ':review:' || (job.metadata ->> 'review_id') ELSE '' END AS scope_key FROM practice_result result JOIN practice practice ON practice.id = result.practice_id LEFT JOIN practice_revision revision ON revision.id = result.practice_revision_id LEFT JOIN agent_job job ON job.id = result.agent_job_id ) derived WHERE derived.id = r.id;
UPDATE practice_result SET evidence = jsonb_set(evidence, '{undecidability}', jsonb_build_array(evidence -> 'undecidability')) WHERE jsonb_typeof(evidence -> 'undecidability') = 'object';
ALTER TABLE practice_result ALTER COLUMN scope_key SET NOT NULL, ADD CONSTRAINT ck_practice_result_scope CHECK (btrim(scope_key) <> ''), ADD CONSTRAINT ck_practice_result_example CHECK (example IS NULL OR (outcome IN ('MET', 'NOT_MET') AND jsonb_typeof(example) = 'object')), ADD CONSTRAINT ck_practice_result_coverage CHECK (coverage IS NULL OR jsonb_typeof(coverage) = 'object'), ADD CONSTRAINT ck_practice_result_provenance CHECK (provenance IS NULL OR jsonb_typeof(provenance) = 'object');

CREATE TABLE practice_observation ( id uuid NOT NULL, workspace_id bigint NOT NULL, practice_result_id uuid NOT NULL, position integer NOT NULL, observation_key varchar(64), severity varchar(16) NOT NULL, summary varchar(255) NOT NULL, explanation text NOT NULL, citations jsonb NOT NULL, basis jsonb, next_step text, recurrence_key varchar(64), CONSTRAINT practice_observation_pkey PRIMARY KEY (id), CONSTRAINT fk_practice_observation_result FOREIGN KEY (practice_result_id, workspace_id) REFERENCES practice_result (id, workspace_id) ON DELETE CASCADE, CONSTRAINT uk_practice_observation_position UNIQUE (practice_result_id, position), CONSTRAINT uk_practice_observation_key UNIQUE (practice_result_id, observation_key), CONSTRAINT uk_practice_observation_parent UNIQUE (id, practice_result_id, workspace_id), CONSTRAINT ck_practice_observation_position CHECK (position >= 0), CONSTRAINT ck_practice_observation_severity CHECK (severity IN ('CRITICAL', 'MAJOR', 'MINOR', 'INFO')), CONSTRAINT ck_practice_observation_key CHECK (observation_key IS NULL OR observation_key ~ '^[a-z0-9][a-z0-9-]{0,63}$'), CONSTRAINT ck_practice_observation_citations CHECK (jsonb_typeof(citations) = 'array'), CONSTRAINT ck_practice_observation_basis CHECK (basis IS NULL OR jsonb_typeof(basis) = 'object') ); CREATE INDEX idx_practice_observation_recurrence ON practice_observation (recurrence_key);
INSERT INTO practice_observation ( id, workspace_id, practice_result_id, position, severity, summary, explanation, citations, recurrence_key) SELECT gen_random_uuid(), workspace_id, id, 0, severity, summary, COALESCE(evidence_rationale, summary), CASE WHEN jsonb_typeof(evidence -> 'citations') = 'array' THEN evidence -> 'citations' ELSE '[]'::jsonb END, recurrence_key FROM practice_result WHERE outcome = 'NOT_MET';
ALTER TABLE practice_result DROP COLUMN recurrence_key;

CREATE FUNCTION public.check_practice_result_children(result_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            result_outcome varchar;
            result_rank integer;
            children bigint;
            worst integer;
        BEGIN
            SELECT r.outcome,
                   CASE r.severity WHEN 'CRITICAL' THEN 3 WHEN 'MAJOR' THEN 2 WHEN 'MINOR' THEN 1 WHEN 'INFO' THEN 0 END
              INTO result_outcome, result_rank
              FROM practice_result r WHERE r.id = result_id;
            IF NOT FOUND THEN
                RETURN;
            END IF;
            SELECT count(*),
                   max(CASE o.severity WHEN 'CRITICAL' THEN 3 WHEN 'MAJOR' THEN 2 WHEN 'MINOR' THEN 1 ELSE 0 END)
              INTO children, worst
              FROM practice_observation o WHERE o.practice_result_id = result_id;
            IF (result_outcome = 'NOT_MET') <> (children > 0) THEN
                RAISE EXCEPTION 'practice result % has % observations, and its outcome is %', result_id, children, result_outcome
                    USING ERRCODE = '23514';
            END IF;
            IF children > 0 AND (result_rank IS NULL OR result_rank < worst) THEN
                RAISE EXCEPTION 'practice result % is less severe than its most severe observation', result_id
                    USING ERRCODE = '23514';
            END IF;
        END;
        $$;

CREATE FUNCTION public.enforce_practice_result_children() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF TG_TABLE_NAME = 'practice_result' THEN
                PERFORM public.check_practice_result_children(NEW.id);
            ELSE
                IF TG_OP <> 'INSERT' THEN
                    PERFORM public.check_practice_result_children(OLD.practice_result_id);
                END IF;
                IF TG_OP <> 'DELETE' THEN
                    PERFORM public.check_practice_result_children(NEW.practice_result_id);
                END IF;
            END IF;
            RETURN NULL;
        END;
        $$;

CREATE CONSTRAINT TRIGGER practice_result_children_consistent
    AFTER INSERT OR UPDATE ON practice_result
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION public.enforce_practice_result_children();

CREATE CONSTRAINT TRIGGER practice_observation_parent_consistent
    AFTER INSERT OR UPDATE OR DELETE ON practice_observation
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION public.enforce_practice_result_children();

DO $$
    DECLARE
        result_id uuid;
    BEGIN
        FOR result_id IN SELECT id FROM practice_result LOOP
            PERFORM public.check_practice_result_children(result_id);
        END LOOP;
    END;
$$;

rollback.sql:
DROP TRIGGER practice_observation_parent_consistent ON practice_observation;
DROP TRIGGER practice_result_children_consistent ON practice_result;
DROP FUNCTION public.enforce_practice_result_children();
DROP FUNCTION public.check_practice_result_children(uuid);

changeSet.sql:
ALTER TABLE feedback_evidence ADD COLUMN id uuid DEFAULT gen_random_uuid(), ADD COLUMN workspace_id bigint, ADD COLUMN observation_id uuid;
UPDATE feedback_evidence e SET workspace_id = f.workspace_id FROM feedback f WHERE f.id = e.feedback_id;
ALTER TABLE feedback_evidence ALTER COLUMN id DROP DEFAULT, ALTER COLUMN id SET NOT NULL, ALTER COLUMN workspace_id SET NOT NULL, DROP CONSTRAINT feedback_evidence_pkey, ADD CONSTRAINT feedback_evidence_pkey PRIMARY KEY (id), ADD CONSTRAINT uk_feedback_evidence_ref UNIQUE NULLS NOT DISTINCT (feedback_id, practice_result_id, observation_id), ADD CONSTRAINT sfk_feedback_evidence_workspace FOREIGN KEY (workspace_id) REFERENCES workspace (id), ADD CONSTRAINT sfk_feedback_evidence_feedback_workspace FOREIGN KEY (workspace_id, feedback_id) REFERENCES feedback (workspace_id, id) ON DELETE CASCADE, ADD CONSTRAINT sfk_feedback_evidence_result_workspace FOREIGN KEY (practice_result_id, workspace_id) REFERENCES practice_result (id, workspace_id) ON DELETE CASCADE, ADD CONSTRAINT sfk_feedback_evidence_observation FOREIGN KEY (observation_id, practice_result_id, workspace_id) REFERENCES practice_observation (id, practice_result_id, workspace_id) ON DELETE CASCADE;
CREATE INDEX idx_feedback_evidence_observation ON feedback_evidence (observation_id);

ALTER TABLE agent_job_practice_script_run DROP CONSTRAINT ck_agent_job_practice_script_run_status, DROP COLUMN leads, ADD COLUMN program_kind varchar(16), ADD COLUMN program_digest varchar(64), ADD COLUMN stop_reason varchar(24), ADD COLUMN calls jsonb, ADD COLUMN coverage_reached jsonb;
UPDATE agent_job_practice_script_run SET program_kind = 'CUSTOM'; UPDATE agent_job_practice_script_run SET status = 'FAILED', stop_reason = 'DEADLINE' WHERE status = 'TIMED_OUT'; UPDATE agent_job_practice_script_run SET stop_reason = 'ERROR' WHERE status IN ('FAILED', 'SKIPPED') AND stop_reason IS NULL;
ALTER TABLE agent_job_practice_script_run ALTER COLUMN program_kind SET NOT NULL, ADD CONSTRAINT ck_agent_job_practice_script_run_status CHECK (status IN ('OK', 'SKIPPED', 'FAILED', 'NOT_REACHED', 'NOT_FINISHED')), ADD CONSTRAINT ck_agent_job_practice_script_run_program_kind CHECK (program_kind IN ('BUILTIN', 'CUSTOM')), ADD CONSTRAINT ck_agent_job_practice_script_run_program_digest CHECK (program_digest IS NULL OR program_digest ~ '^[0-9a-f]{64}$'), ADD CONSTRAINT ck_agent_job_practice_script_run_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ( 'UNAVAILABLE', 'BUDGET', 'DEADLINE', 'TOO_LARGE', 'OFF_FORMAT', 'REFUSED', 'ERROR', 'CANCELLED', 'INVALID_PROGRAM', 'INVALID_CANDIDATE')), ADD CONSTRAINT ck_agent_job_practice_script_run_stop CHECK ((status IN ('OK', 'NOT_FINISHED')) = (stop_reason IS NULL)), ADD CONSTRAINT ck_agent_job_practice_script_run_calls CHECK (calls IS NULL OR jsonb_typeof(calls) = 'object'), ADD CONSTRAINT ck_agent_job_practice_script_run_coverage CHECK (coverage_reached IS NULL OR jsonb_typeof(coverage_reached) = 'object');
